import java.util.*; class Solution { public int longestIncreasingPath(int[][] matrix) { if (matrix == null || matrix.length == 0) return 0; int m = matrix.length; int n = matrix[0].length; int[][] cache = new int[m][n]; int maxPath = 0; for (int i = 0; i < m; i++) { for (int j = 0; j < n; j++) { maxPath = Math.max(maxPath, dfs(matrix, i, j, cache)); } } return maxPath; } private int dfs(int[][] matrix, int i, int j, int[][] cache) { if (cache[i][j] != 0) return cache[i][j]; int m = matrix.length; int n = matrix[0].length; int max = 1; int[] dx = {0, 0, 1, -1}; int[] dy = {1, -1, 0, 0}; for (int k = 0; k < 4; k++) { int ni = i + dx[k]; int nj = j + dy[k]; if (ni >= 0 && ni < m && nj >= 0 && nj < n && matrix[ni][nj] > matrix[i][j]) { max = Math.max(max, 1 + dfs(matrix, ni, nj, cache)); } } cache[i][j] = max; return max; } }